<template>
	<view class="container">
		<!-- 自定义导航栏 -->
		<view class="custom-navbar">
			<view class="navbar-content">
				<view class="nav-left" @click="goBack">
					<image class="back-icon" src="/static/back.png" mode="aspectFit"></image>
				</view>
				<view class="nav-center">
					<view class="nav-title">{{ chatUser.name }}</view>
					<view class="connection-status" :class="{ offline: !isOnline, connecting: isConnecting }">
						<view class="status-dot"></view>
						<text class="status-text">
							{{ isConnecting ? '连接中...' : (isOnline ? '在线' : '离线') }}
						</text>
					</view>
				</view>
				<view class="nav-right" @click="makeCall">
					<image class="phone-icon" src="/static/phone.png" mode="aspectFit"></image>
				</view>
			</view>
		</view>
		
		<!-- 聊天消息列表 -->
		<scroll-view 
			class="message-list" 
			scroll-y 
			:scroll-top="scrollTop"
			:scroll-with-animation="true"
			@scrolltoupper="loadMoreMessages"
			:refresher-enabled="true"
			:refresher-triggered="isLoadingMore"
			@refresherrefresh="onRefresh"
		>
			<!-- 加载更多指示器 -->
			<view v-if="isLoadingMore" class="loading-indicator">
				<view class="loading-icon"></view>
				<text class="loading-text">加载历史消息中...</text>
			</view>
			
			<!-- 没有更多消息提示 -->
			<view v-else-if="!hasMoreMessages && messageList.length > pageSize" class="no-more-indicator">
				<text>已显示全部历史消息</text>
			</view>
			
			<!-- 同步状态指示器 -->
			<view class="sync-indicator" v-if="isConnecting">
				<view class="sync-loading"></view>
				<text class="sync-text">正在同步消息...</text>
			</view>
			
			<!-- 离线提示 -->
			<view class="offline-banner" v-if="!isOnline">
				<text class="offline-text">⚠️ 网络连接断开，消息将在网络恢复后发送</text>
			</view>
			
			<!-- 正在输入提示 -->
			<view v-if="isTyping" class="typing-indicator">
				<view class="typing-dots">
					<view class="dot"></view>
					<view class="dot"></view>
					<view class="dot"></view>
				</view>
				<text>{{chatUser.name}} 正在输入...</text>
			</view>
			
			<view class="message-item" v-for="(message, index) in messageList" :key="index" @longpress="showMessageMenu(message, $event)">
				<!-- 时间分割线 -->
				<view class="time-divider" v-if="showTimeDivider(index)">
					<text>{{ formatTime(message.timestamp) }}</text>
				</view>
				
				<!-- 消息内容 -->
				<view class="message-wrapper" :class="{ 'is-mine': message.isMine }">
					<image 
						class="avatar" 
						:src="message.isMine ? myAvatar : chatUser.avatar" 
						mode="aspectFill"
					></image>
					
					<view class="message-content">
						<!-- 文本消息 -->
						<view class="text-message" v-if="message.type === 'text'">
							<text>{{ message.content }}</text>
						</view>
						
						<!-- 图片消息 -->
						<view class="image-message" v-else-if="message.type === 'image'">
							<image 
								:src="message.content" 
								mode="aspectFit"
								@click="previewImage(message.content)"
							></image>
						</view>
						
						<!-- 语音消息 -->
						<view class="voice-message" v-else-if="message.type === 'voice'" @click="playVoice(message)">
							<image class="voice-icon" src="/static/voice.png" mode="aspectFit"></image>
							<text class="voice-duration">{{ message.duration }}"</text>
						</view>
						
						<!-- 位置消息 -->
						<view class="location-message" v-else-if="message.type === 'location'" @click="openLocation(message)">
							<image class="location-icon" src="/static/location.png" mode="aspectFit"></image>
							<view class="location-info">
								<text class="location-name">{{ message.locationName }}</text>
								<text class="location-address">{{ message.locationAddress }}</text>
							</view>
						</view>
						
						<!-- 系统消息 -->
						<view class="system-message" v-else-if="message.type === 'system'">
							<text class="system-text">{{ message.content }}</text>
						</view>
						
						<!-- 消息状态 -->
						<view class="message-status" v-if="message.isMine && message.status">
							<text class="status-text" :class="message.status">
								{{ getStatusText(message.status) }}
							</text>
							<view class="status-icon" :class="message.status" @click="handleStatusClick(message)">
								<text v-if="message.status === 'sending'">⏳</text>
								<text v-else-if="message.status === 'sent'">✓</text>
								<text v-else-if="message.status === 'read'">✓✓</text>
								<text v-else-if="message.status === 'failed'" class="retry-icon">⚠️</text>
							</view>
						</view>
					</view>
				</view>
			</view>
		</scroll-view>
		
		<!-- 消息操作菜单 -->
		<view class="message-menu" v-if="showMenu" :style="{ left: menuPosition.x + 'px', top: menuPosition.y + 'px' }" @click="hideMessageMenu">
			<view class="menu-item" @click.stop="copyMessage" v-if="selectedMessage && selectedMessage.type === 'text'">
				<text class="menu-icon">📋</text>
				<text class="menu-text">复制</text>
			</view>
			<view class="menu-item" @click.stop="recallMessage" v-if="selectedMessage && selectedMessage.isMine && canRecall(selectedMessage)">
				<text class="menu-icon">↩️</text>
				<text class="menu-text">撤回</text>
			</view>
			<view class="menu-item" @click.stop="deleteMessage" v-if="selectedMessage">
				<text class="menu-icon">🗑️</text>
				<text class="menu-text">删除</text>
			</view>
		</view>
		
		<!-- 遮罩层 -->
		<view class="menu-mask" v-if="showMenu" @click="hideMessageMenu"></view>
		
		<!-- 输入区域 -->
		<view class="input-area">
			<!-- 聊天工具栏 -->
			<view class="chat-toolbar">
				<text class="toolbar-btn" @click="toggleSearch">🔍 搜索</text>
				<text class="toolbar-btn" @click="clearChatHistory">🗑️ 清空聊天</text>
				<text class="toolbar-btn" @click="exportChatHistory">📤 导出记录</text>
			</view>
			
			<!-- 搜索栏 -->
			<view v-if="showSearchBar" class="search-bar">
				<input 
					v-model="searchKeyword" 
					placeholder="搜索聊天记录..." 
					class="search-input"
					@input="onSearchInput"
					@confirm="searchMessages"
				/>
				<text class="search-btn" @click="searchMessages">搜索</text>
				<text class="close-btn" @click="closeSearch">✕</text>
			</view>
			
			<!-- 快捷回复面板 -->
			<view v-if="showQuickReply" class="quick-reply-panel">
				<view class="quick-reply-header">
					<text>快捷回复</text>
					<text class="close-btn" @click="showQuickReply = false">✕</text>
				</view>
				<view class="quick-reply-list">
					<text class="quick-reply-item" @click="sendQuickReply('好的')">好的</text>
					<text class="quick-reply-item" @click="sendQuickReply('收到')">收到</text>
					<text class="quick-reply-item" @click="sendQuickReply('谢谢')">谢谢</text>
					<text class="quick-reply-item" @click="sendQuickReply('稍等')">稍等</text>
					<text class="quick-reply-item" @click="sendQuickReply('没问题')">没问题</text>
					<text class="quick-reply-item" @click="sendQuickReply('辛苦了')">辛苦了</text>
				</view>
			</view>
			
			<!-- 表情包面板 -->
			<view v-if="showEmojiPanel" class="emoji-panel">
				<view class="emoji-header">
					<text>表情</text>
					<text class="close-btn" @click="showEmojiPanel = false">✕</text>
				</view>
				<view class="emoji-grid">
					<text class="emoji-item" @click="insertEmoji('😀')">😀</text>
					<text class="emoji-item" @click="insertEmoji('😃')">😃</text>
					<text class="emoji-item" @click="insertEmoji('😄')">😄</text>
					<text class="emoji-item" @click="insertEmoji('😁')">😁</text>
					<text class="emoji-item" @click="insertEmoji('😆')">😆</text>
					<text class="emoji-item" @click="insertEmoji('😅')">😅</text>
					<text class="emoji-item" @click="insertEmoji('😂')">😂</text>
					<text class="emoji-item" @click="insertEmoji('🤣')">🤣</text>
					<text class="emoji-item" @click="insertEmoji('😊')">😊</text>
					<text class="emoji-item" @click="insertEmoji('😇')">😇</text>
					<text class="emoji-item" @click="insertEmoji('🙂')">🙂</text>
					<text class="emoji-item" @click="insertEmoji('🙃')">🙃</text>
					<text class="emoji-item" @click="insertEmoji('😉')">😉</text>
					<text class="emoji-item" @click="insertEmoji('😌')">😌</text>
					<text class="emoji-item" @click="insertEmoji('😍')">😍</text>
					<text class="emoji-item" @click="insertEmoji('🥰')">🥰</text>
					<text class="emoji-item" @click="insertEmoji('😘')">😘</text>
					<text class="emoji-item" @click="insertEmoji('😗')">😗</text>
					<text class="emoji-item" @click="insertEmoji('😙')">😙</text>
					<text class="emoji-item" @click="insertEmoji('😚')">😚</text>
					<text class="emoji-item" @click="insertEmoji('😋')">😋</text>
					<text class="emoji-item" @click="insertEmoji('😛')">😛</text>
					<text class="emoji-item" @click="insertEmoji('😝')">😝</text>
					<text class="emoji-item" @click="insertEmoji('😜')">😜</text>
				</view>
			</view>
			
			<view class="input-wrapper">
				<text class="action-btn" @click="showQuickReply = !showQuickReply">💬</text>
				<text class="action-btn" @click="showEmojiPanel = !showEmojiPanel">😀</text>
				<image class="voice-btn" src="/static/voice.png" mode="aspectFit" @click="toggleVoiceInput"></image>
				
				<input 
					v-if="!isVoiceInput"
					class="text-input" 
					v-model="inputText" 
					placeholder="请输入消息..."
					@confirm="sendTextMessage"
					:focus="inputFocus"
					@input="onInputChange"
				/>
				
				<view 
					v-else
					class="voice-input"
					@touchstart="startRecord"
					@touchend="stopRecord"
					@touchcancel="cancelRecord"
				>
					<text>{{ isRecording ? '松开发送' : '按住说话' }}</text>
				</view>
				
				<view class="action-buttons">
					<image class="action-btn" src="/static/image.png" mode="aspectFit" @click="chooseImage"></image>
					<image class="action-btn" src="/static/location.png" mode="aspectFit" @click="sendLocation"></image>
					<button 
						class="send-btn" 
						v-if="inputText.trim() && !isVoiceInput"
						@click="sendTextMessage"
					>
						发送
					</button>
				</view>
			</view>
		</view>
	</view>
</template>

<script setup>
import { ref, nextTick, onMounted, onUnmounted } from 'vue'

// 响应式数据
const chatUser = ref({
	id: '',
	name: '',
	avatar: '/static/avatar1.png'
})

const myAvatar = ref('/static/doctor-avatar.png')

const messageList = ref([])
const chatId = ref('')
const syncTimer = ref(null)
const lastSyncTime = ref(0)
const isOnline = ref(true)
const isConnecting = ref(false)
const retryCount = ref(0)
const maxRetries = ref(3)
const showMenu = ref(false)
const menuPosition = ref({ x: 0, y: 0 })
const selectedMessage = ref(null)
const isLoadingMore = ref(false)
const hasMoreMessages = ref(true)
const pageSize = ref(20)
const currentPage = ref(1)
const showSearchBar = ref(false)
const searchKeyword = ref('')
const searchResults = ref([])
const showEmojiPanel = ref(false)
const showQuickReply = ref(false)
const isTyping = ref(false)
const typingTimer = ref(null)

const inputText = ref('')
const inputFocus = ref(false)
const isVoiceInput = ref(false)
const isRecording = ref(false)
const scrollTop = ref(0)
const recorderManager = ref(null)
const innerAudioContext = ref(null)

// 生命周期
onMounted(() => {
	// 从路由参数获取用户信息
	const pages = getCurrentPages()
	const currentPage = pages[pages.length - 1]
	const options = currentPage.options
	
	if (options.userId) {
		chatUser.value.id = options.userId
	}
	if (options.name) {
		chatUser.value.name = decodeURIComponent(options.name)
	}
	
	// 监听网络状态
	uni.onNetworkStatusChange((res) => {
		isOnline.value = res.isConnected
		if (res.isConnected) {
			uni.showToast({
				title: '网络已连接',
				icon: 'success',
				duration: 1500
			})
			// 重新开始同步
			startMessageSync()
			// 重试失败的消息
			retryFailedMessages()
		} else {
			uni.showToast({
				title: '网络连接断开',
				icon: 'none',
				duration: 2000
			})
			// 停止同步
			stopMessageSync()
		}
	})
	
	// 获取当前网络状态
	uni.getNetworkType({
		success: (res) => {
			isOnline.value = res.networkType !== 'none'
		}
	})
	
	// 初始化聊天
	initChat()
	// 开始消息同步
	startMessageSync()
	
	// 滚动到底部
	nextTick(() => {
		scrollToBottom()
	})
})

onUnmounted(() => {
	// 停止消息同步
	stopMessageSync()
})

// 方法定义
// 返回
const goBack = () => {
	uni.navigateBack()
}

// 拨打电话
const makeCall = () => {
	uni.makePhoneCall({
		phoneNumber: '138****8888'
	})
}

// 显示时间分割线
const showTimeDivider = (index) => {
	if (index === 0) return true
	
	const current = messageList.value[index]
	const previous = messageList.value[index - 1]
	
	// 如果两条消息间隔超过5分钟，显示时间
	return current.timestamp - previous.timestamp > 300000
}

// 格式化时间
const formatTime = (timestamp) => {
	const date = new Date(timestamp)
	const now = new Date()
	
	if (date.toDateString() === now.toDateString()) {
		// 今天，显示时间
		return date.toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' })
	} else {
		// 其他日期，显示日期和时间
		return date.toLocaleString('zh-CN', { 
			month: '2-digit', 
			day: '2-digit', 
			hour: '2-digit', 
			minute: '2-digit' 
		})
	}
}

// 发送文本消息
const sendTextMessage = () => {
	if (!inputText.value.trim()) return
	
	const message = {
		id: Date.now(),
		type: 'text',
		content: inputText.value.trim(),
		isMine: true,
		timestamp: Date.now(),
		status: 'sending' // 发送状态
	}
	
	messageList.value.push(message)
	inputText.value = ''
	
	// 保存到本地存储
	saveMessagesToLocal()
	
	// 发送到服务器
	sendMessageToServer(message)
	
	nextTick(() => {
		scrollToBottom()
	})
}

// 发送消息到服务器
const sendMessageToServer = async (message) => {
	// 使用增强版发送方法
	await sendMessageToServerEnhanced(message)
}

// 切换语音输入
const toggleVoiceInput = () => {
	isVoiceInput.value = !isVoiceInput.value
	inputFocus.value = !isVoiceInput.value
}

// 开始录音
const startRecord = () => {
	isRecording.value = true
	
	if (!recorderManager.value) {
		recorderManager.value = uni.getRecorderManager()
		
		recorderManager.value.onStart(() => {
			console.log('录音开始')
		})
		
		recorderManager.value.onStop((res) => {
			console.log('录音结束', res)
			if (res.duration > 1000) { // 录音时长大于1秒才发送
				sendVoiceMessage(res.tempFilePath, Math.floor(res.duration / 1000))
			} else {
				uni.showToast({
					title: '录音时间太短',
					icon: 'none'
				})
			}
		})
		
		recorderManager.value.onError((err) => {
			console.error('录音错误', err)
			uni.showToast({
				title: '录音失败',
				icon: 'none'
			})
			isRecording.value = false
		})
	}
	
	recorderManager.value.start({
		duration: 60000, // 最长60秒
		sampleRate: 16000,
		numberOfChannels: 1,
		encodeBitRate: 96000,
		format: 'mp3'
	})
}

// 停止录音
const stopRecord = () => {
	isRecording.value = false
	if (recorderManager.value) {
		recorderManager.value.stop()
	}
}

// 取消录音
const cancelRecord = () => {
	isRecording.value = false
	if (recorderManager.value) {
		recorderManager.value.stop()
	}
	uni.showToast({
		title: '录音取消',
		icon: 'none'
	})
}

// 选择图片
const chooseImage = () => {
	uni.chooseImage({
		count: 1,
		sourceType: ['album', 'camera'],
		sizeType: ['compressed'], // 压缩图片
		success: (res) => {
			const tempFilePath = res.tempFilePaths[0]
			
			// 显示上传进度
			uni.showLoading({
				title: '图片处理中...'
			})
			
			// 压缩图片
			uni.compressImage({
				src: tempFilePath,
				quality: 80, // 压缩质量
				success: (compressRes) => {
					uni.hideLoading()
					
					// 创建图片消息
					const message = {
						id: Date.now(),
						type: 'image',
						content: compressRes.tempFilePath,
						isMine: true,
						timestamp: Date.now(),
						status: 'sending' // 发送状态
					}
					
					messageList.value.push(message)
			
			// 保存到本地存储
			saveMessagesToLocal()
			
			nextTick(() => {
				scrollToBottom()
			})
			
			// 模拟上传过程
			uploadImage(message, compressRes.tempFilePath)
				},
				fail: (err) => {
					uni.hideLoading()
					console.error('图片压缩失败', err)
					
					// 使用原图
					const message = {
						id: Date.now(),
						type: 'image',
						content: tempFilePath,
						isMine: true,
						timestamp: Date.now(),
						status: 'sending'
					}
					
					messageList.value.push(message)
			
			// 保存到本地存储
			saveMessagesToLocal()
			
			nextTick(() => {
				scrollToBottom()
			})
			
			uploadImage(message, tempFilePath)
				}
			})
		},
		fail: (err) => {
			console.error('选择图片失败', err)
			uni.showToast({
				title: '选择图片失败',
				icon: 'none'
			})
		}
	})
}

// 上传图片
const uploadImage = (message, filePath) => {
	// TODO: 实际上传到服务器
	// 这里模拟上传过程
	setTimeout(() => {
		// 更新消息状态为已发送
		const index = messageList.value.findIndex(m => m.id === message.id)
		if (index !== -1) {
			messageList.value[index].status = 'sent'
		}
		
		uni.showToast({
			title: '图片发送成功',
			icon: 'success'
		})
	}, 2000)
}

// 发送位置
const sendLocation = () => {
	uni.chooseLocation({
		success: (res) => {
			const message = {
				id: Date.now(),
				type: 'location',
				locationName: res.name,
				locationAddress: res.address,
				latitude: res.latitude,
				longitude: res.longitude,
				isMine: true,
				timestamp: Date.now(),
				status: 'sending'
			}
			
			messageList.value.push(message)
		
		// 保存到本地存储
		saveMessagesToLocal()
		
		// 发送位置消息
		sendMessageToServer(message)
		
		nextTick(() => {
			scrollToBottom()
		})
		}
	})
}

// 获取状态文本
const getStatusText = (status) => {
	switch (status) {
		case 'sending':
			return '发送中'
		case 'sent':
			return '已发送'
		case 'read':
			return '已读'
		case 'failed':
			return '发送失败'
		default:
			return ''
	}
}

// 处理状态点击
const handleStatusClick = (message) => {
	if (message.status === 'failed') {
		// 重试发送
		retryMessage(message)
	}
}

// 重试发送消息
const retryMessage = async (message) => {
	try {
		// 更新状态为发送中
		const index = messageList.value.findIndex(m => m.id === message.id)
		if (index !== -1) {
			messageList.value[index].status = 'sending'
			saveMessagesToLocal()
		}
		
		// 重新发送
		await sendMessageToServerEnhanced(message)
		
		uni.showToast({
			title: '重新发送中...',
			icon: 'loading'
		})
	} catch (error) {
		console.error('重试发送失败:', error)
	}
}

// 显示消息菜单
const showMessageMenu = (message, event) => {
	selectedMessage.value = message
	
	// 获取触摸位置
	const touch = event.touches ? event.touches[0] : event
	menuPosition.value = {
		x: touch.clientX || touch.pageX || 0,
		y: touch.clientY || touch.pageY || 0
	}
	
	// 调整菜单位置，避免超出屏幕
	const screenWidth = uni.getSystemInfoSync().windowWidth
	const screenHeight = uni.getSystemInfoSync().windowHeight
