// 判断是否可以撤回
const canRecall = (message) => {
	// 只能撤回2分钟内的消息
	const now = Date.now()
	const messageTime = message.timestamp
	return (now - messageTime) < 2 * 60 * 1000
}

// 撤回消息
const recallMessage = async () => {
