// 滚动到底部
const scrollToBottom = () => {
	scrollTop.value = 999999
}

// 初始化聊天
const initChat = async () => {
	try {
		// 生成或获取聊天ID
		chatId.value = `chat_${chatUser.value.id}_${Date.now()}`
		
		// 从本地存储加载最近的消息（第一页）
		const recentMessages = await loadHistoryMessages(1)
		if (recentMessages && recentMessages.length > 0) {
			messageList.value = recentMessages
			currentPage.value = 1
			lastSyncTime.value = Math.max(...recentMessages.map(m => m.timestamp))
			
			// 检查是否还有更多消息
			if (recentMessages.length < pageSize.value) {
				hasMoreMessages.value = false
			}
		} else {
			// 如果没有本地消息，添加默认欢迎消息
			const welcomeMessage = {
				id: Date.now(),
				type: 'text',
				content: '您好，我是您的陪诊师，请问您现在在哪里？',
				isMine: true,
				timestamp: Date.now(),
				status: 'read'
			}
			messageList.value = [welcomeMessage]
			saveMessagesToLocal()
			hasMoreMessages.value = false
		}
		
		// 从服务器同步最新消息
		await syncMessagesFromServer()
		
		nextTick(() => {
			scrollToBottom()
		})
	} catch (error) {
		console.error('初始化聊天失败:', error)
		uni.showToast({
			title: '聊天初始化失败',
			icon: 'none'
		})
	}
}

// 开始消息同步
const startMessageSync = () => {
	// 每5秒同步一次消息
	syncTimer.value = setInterval(async () => {
		await syncMessagesFromServer()
	}, 5000)
}

// 停止消息同步
const stopMessageSync = () => {
	if (syncTimer.value) {
		clearInterval(syncTimer.value)
		syncTimer.value = null
	}
}

// 从服务器同步消息
const syncMessagesFromServer = async () => {
	try {
		// 检查网络状态
		if (!isOnline.value) {
			console.log('网络未连接，跳过同步')
			return
		}
		
		isConnecting.value = true
		
		// TODO: 实际的API调用
		// const response = await uni.request({
		//   url: '/api/chat/sync',
		//   method: 'POST',
		//   data: {
		//     chatId: chatId.value,
		//     userId: chatUser.value.id,
		//     lastSyncTime: lastSyncTime.value
		//   }
		// })
		
		// 模拟服务器响应
		const mockResponse = {
			data: {
				success: true,
				messages: [], // 新消息列表
				updatedMessages: [] // 更新的消息状态
			}
		}
		
		const { messages: newMessages, updatedMessages } = mockResponse.data
		
		// 添加新消息
		if (newMessages && newMessages.length > 0) {
			newMessages.forEach(message => {
				// 检查消息是否已存在
				const existingIndex = messageList.value.findIndex(m => m.id === message.id)
				if (existingIndex === -1) {
					messageList.value.push(message)
					lastSyncTime.value = Math.max(lastSyncTime.value, message.timestamp)
				}
			})
			
			// 按时间排序
			messageList.value.sort((a, b) => a.timestamp - b.timestamp)
			
			// 滚动到底部
			nextTick(() => {
				scrollToBottom()
			})
		}
		
		// 更新消息状态
		if (updatedMessages && updatedMessages.length > 0) {
			updatedMessages.forEach(update => {
				const messageIndex = messageList.value.findIndex(m => m.id === update.id)
				if (messageIndex !== -1) {
					messageList.value[messageIndex] = { ...messageList.value[messageIndex], ...update }
				}
			})
		}
		
		// 保存到本地存储
		saveMessagesToLocal()
		
		// 重置重试计数
		retryCount.value = 0
		
	} catch (error) {
		console.error('同步消息失败:', error)
		
		// 增加重试计数
		retryCount.value++
		
		// 如果重试次数未达到上限，延迟重试
		if (retryCount.value < maxRetries.value) {
			setTimeout(() => {
				syncMessagesFromServer()
			}, 5000 * retryCount.value) // 递增延迟
		} else {
			uni.showToast({
				title: '同步失败，请检查网络',
				icon: 'none',
				duration: 2000
			})
		}
	} finally {
		isConnecting.value = false
	}
}

// 保存消息到本地存储
const saveMessagesToLocal = () => {
	try {
		// 保存当前会话消息
		uni.setStorageSync(`messages_${chatUser.value.id}`, messageList.value)
		uni.setStorageSync(`lastSyncTime_${chatUser.value.id}`, lastSyncTime.value)
		
		// 保存到全部历史消息
		saveToAllMessages()
	} catch (error) {
		console.error('保存消息到本地失败:', error)
	}
}

// 保存到全部历史消息
const saveToAllMessages = () => {
	try {
		// 获取现有的全部历史消息
		const allMessages = uni.getStorageSync(`all_messages_${chatUser.value.id}`) || []
		
		// 合并当前消息列表
		const mergedMessages = [...allMessages]
		
		// 添加新消息（避免重复）
		messageList.value.forEach(message => {
			const existingIndex = mergedMessages.findIndex(m => m.id === message.id)
			if (existingIndex === -1) {
				mergedMessages.push(message)
			} else {
				// 更新现有消息
				mergedMessages[existingIndex] = message
			}
		})
		
		// 按时间排序
		mergedMessages.sort((a, b) => a.timestamp - b.timestamp)
		
		// 限制历史消息数量（保留最近1000条）
		const maxHistoryMessages = 1000
		if (mergedMessages.length > maxHistoryMessages) {
			mergedMessages.splice(0, mergedMessages.length - maxHistoryMessages)
		}
		
		// 保存到本地存储
		uni.setStorageSync(`all_messages_${chatUser.value.id}`, mergedMessages)
	} catch (error) {
		console.error('保存到全部历史消息失败:', error)
	}
}

// 重试失败的消息
const retryFailedMessages = async () => {
	const failedMessages = messageList.value.filter(m => m.isMine && m.status === 'failed')
	for (const message of failedMessages) {
		await sendMessageToServerEnhanced(message)
	}
}

// 加载更多消息
const loadMoreMessages = async () => {
	if (isLoadingMore.value || !hasMoreMessages.value) {
		return
	}
	
	isLoadingMore.value = true
	
	try {
		// 从本地存储加载更多历史消息
		const moreMessages = await loadHistoryMessages(currentPage.value + 1)
		
		if (moreMessages && moreMessages.length > 0) {
			// 将新消息插入到列表开头
			messageList.value.unshift(...moreMessages)
			currentPage.value++
			
			// 检查是否还有更多消息
			if (moreMessages.length < pageSize.value) {
				hasMoreMessages.value = false
			}
			
			uni.showToast({
				title: `加载了 ${moreMessages.length} 条历史消息`,
				icon: 'success',
				duration: 1500
			})
		} else {
			hasMoreMessages.value = false
			uni.showToast({
				title: '没有更多历史消息了',
				icon: 'none',
				duration: 1500
			})
		}
	} catch (error) {
		console.error('加载历史消息失败:', error)
		uni.showToast({
			title: '加载失败，请重试',
			icon: 'none'
		})
	} finally {
		isLoadingMore.value = false
	}
}

// 下拉刷新处理
const onRefresh = async () => {
	await loadMoreMessages()
}

// 从本地存储加载历史消息
const loadHistoryMessages = async (page) => {
	try {
		// 从本地存储获取所有历史消息
		const allMessages = uni.getStorageSync(`all_messages_${chatUser.value.id}`) || []
		
		// 按时间倒序排列
		allMessages.sort((a, b) => b.timestamp - a.timestamp)
		
		// 计算分页
		const startIndex = (page - 1) * pageSize.value
		const endIndex = startIndex + pageSize.value
		
		// 获取当前页的消息
		const pageMessages = allMessages.slice(startIndex, endIndex)
		
		// 返回按时间正序排列的消息
		return pageMessages.reverse()
	} catch (error) {
		console.error('从本地存储加载历史消息失败:', error)
		return []
	}
}

// 清空聊天记录
const clearChatHistory = () => {
	uni.showModal({
		title: '确认清空',
		content: '确定要清空所有聊天记录吗？此操作不可恢复。',
		success: (res) => {
			if (res.confirm) {
				// 清空当前消息列表
				messageList.value = []
				
				// 清空本地存储
				try {
					uni.removeStorageSync(`messages_${chatUser.value.id}`)
					uni.removeStorageSync(`all_messages_${chatUser.value.id}`)
					uni.removeStorageSync(`lastSyncTime_${chatUser.value.id}`)
					
					// 重置相关状态
					lastSyncTime.value = 0
					currentPage.value = 1
					hasMoreMessages.value = true
					
					uni.showToast({
						title: '聊天记录已清空',
						icon: 'success'
					})
				} catch (error) {
					console.error('清空聊天记录失败:', error)
					uni.showToast({
						title: '清空失败',
						icon: 'none'
					})
				}
			}
		}
	})
}

// 切换搜索栏
const toggleSearch = () => {
	showSearchBar.value = !showSearchBar.value
	if (!showSearchBar.value) {
		searchKeyword.value = ''
		searchResults.value = []
	}
}

// 关闭搜索
const closeSearch = () => {
	showSearchBar.value = false
	searchKeyword.value = ''
	searchResults.value = []
}

// 搜索输入处理
const onSearchInput = () => {
	if (searchKeyword.value.trim()) {
		searchMessages()
	} else {
		searchResults.value = []
	}
}

// 搜索消息
const searchMessages = () => {
	if (!searchKeyword.value.trim()) {
		return
	}
	
	try {
		const allMessages = uni.getStorageSync(`all_messages_${chatUser.value.id}`) || []
		const results = allMessages.filter(message => {
			if (message.type === 'text') {
				return message.content.toLowerCase().includes(searchKeyword.value.toLowerCase())
			}
			return false
		})
		
		searchResults.value = results
		
		if (results.length > 0) {
			uni.showToast({
				title: `找到 ${results.length} 条相关消息`,
				icon: 'success'
			})
		} else {
			uni.showToast({
				title: '未找到相关消息',
				icon: 'none'
			})
		}
	} catch (error) {
		console.error('搜索消息失败:', error)
		uni.showToast({
			title: '搜索失败',
			icon: 'none'
		})
	}
}

// 插入表情
const insertEmoji = (emoji) => {
	inputText.value += emoji
	showEmojiPanel.value = false
}

// 发送快捷回复
const sendQuickReply = (text) => {
	inputText.value = text
	showQuickReply.value = false
	sendTextMessage()
}

// 输入变化处理
const onInputChange = () => {
	// 显示正在输入状态
	isTyping.value = true
	
	// 清除之前的定时器
	if (typingTimer.value) {
		clearTimeout(typingTimer.value)
	}
	
	// 设置新的定时器，2秒后隐藏正在输入状态
	typingTimer.value = setTimeout(() => {
		isTyping.value = false
	}, 2000)
}

// 导出聊天记录
const exportChatHistory = () => {
	try {
		const allMessages = uni.getStorageSync(`all_messages_${chatUser.value.id}`) || []
		
		if (allMessages.length === 0) {
			uni.showToast({
				title: '暂无聊天记录',
				icon: 'none'
			})
			return
		}
		
		// 格式化聊天记录为文本
		let exportText = `聊天记录 - ${chatUser.value.name}\n`
		exportText += `导出时间: ${new Date().toLocaleString()}\n`
		exportText += `消息总数: ${allMessages.length}\n`
		exportText += '\n' + '='.repeat(50) + '\n\n'
		
		allMessages.forEach(message => {
			const time = new Date(message.timestamp).toLocaleString()
			const sender = message.isMine ? '我' : chatUser.value.name
			
			let content = ''
			switch (message.type) {
				case 'text':
					content = message.content
					break
				case 'image':
					content = '[图片]'
					break
				case 'voice':
					content = `[语音 ${message.duration}秒]`
					break
				case 'location':
					content = `[位置] ${message.locationName}`
					break
				case 'system':
					content = `[系统消息] ${message.content}`
					break
				default:
					content = '[未知消息类型]'
			}
			
			exportText += `[${time}] ${sender}: ${content}\n`
		})
		
		// 复制到剪贴板
		uni.setClipboardData({
			data: exportText,
			success: () => {
				uni.showToast({
					title: '聊天记录已复制到剪贴板',
					icon: 'success',
					duration: 2000
				})
			},
			fail: () => {
				uni.showToast({
					title: '导出失败',
					icon: 'none'
				})
			}
		})
	} catch (error) {
		console.error('导出聊天记录失败:', error)
		uni.showToast({
			title: '导出失败',
			icon: 'none'
		})
	}
}

// 发送消息到服务器（增强版）
const sendMessageToServerEnhanced = async (message) => {
	try {
		// 检查网络状态
		if (!isOnline.value) {
			throw new Error('网络未连接')
		}
		
		// TODO: 实际的API调用
		// const response = await uni.request({
		//   url: '/api/chat/send',
		//   method: 'POST',
		//   data: {
		//     chatId: chatId.value,
		//     message: message,
		//     userId: chatUser.value.id
		//   }
		// })
		
		// 模拟发送过程
		await new Promise(resolve => setTimeout(resolve, 1000))
		
		// 更新消息状态为已发送
		const index = messageList.value.findIndex(m => m.id === message.id)
		if (index !== -1) {
			messageList.value[index].status = 'sent'
			messageList.value[index].serverMessageId = `server_${message.id}`
			
			// 保存到本地
			saveMessagesToLocal()
			
			// 模拟已读状态（延迟更新）
			setTimeout(() => {
				if (messageList.value[index]) {
					messageList.value[index].status = 'read'
					saveMessagesToLocal()
				}
			}, 3000)
		}
		
		return { success: true }
	} catch (error) {
		console.error('发送消息失败:', error)
		
		// 更新消息状态为发送失败
		const index = messageList.value.findIndex(m => m.id === message.id)
		if (index !== -1) {
			messageList.value[index].status = 'failed'
			saveMessagesToLocal()
		}
		
		// 根据错误类型显示不同提示
		let errorMessage = '发送失败，请重试'
		if (error.message === '网络未连接') {
			errorMessage = '网络未连接，消息将在网络恢复后重试'
		} else if (error.message.includes('timeout')) {
			errorMessage = '网络超时，请检查网络连接'
		}
		
		uni.showToast({
			title: errorMessage,
			icon: 'none',
			duration: 2000
		})
		
		return { success: false, error }
	}
}
</script>

